sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    function nameOf(id) {
        if (!id) return 'None';
        var u = new GlideRecord('sys_user');
        if (u.get(id)) {
            return u.getValue('name');
        }
        return 'None';
    }

    var prevAgentName = nameOf(event.parm1);
    var newAgentName  = nameOf(event.parm2);

    template.print('<tr style="border-bottom: 1px solid #e1e4e8;">');
    template.print('<td width="35%" style="font-weight: 600; color: #555555;">Previous Assignee:</td>');
    template.print('<td>' + prevAgentName + '</td>');
    template.print('</tr>');

    template.print('<tr style="background-color: #f8f9fa; border-bottom: 1px solid #e1e4e8;">');
    template.print('<td style="font-weight: 600; color: #555555;">New Assignee:</td>');
    template.print('<td style="font-weight: 600; color: #28a745;">' + newAgentName + '</td>');
    template.print('</tr>');

})(current, template, email, email_action, event);
